function useReveal(t=0.15){const r=useRef(null);const[v,sV]=useState(false);useEffect(()=>{const e=r.current;if(!e)return;const o=new IntersectionObserver(([x])=>{if(x.isIntersecting){sV(true);o.disconnect()}},{threshold:t});o.observe(e);return()=>o.disconnect()},[t]);return[r,v]}
function Reveal({children,delay=0,style={}}){const[r,v]=useReveal();return <div ref={r} style={{opacity:v?1:0,transform:v?"translateY(0)":"translateY(32px)",transition:`all .8s cubic-bezier(.22,1,.36,1) ${delay}s`,...style}}>{children}</div>}
function Counter({end,suffix="",duration=2200}){const[c,sC]=useState(0);const[r,v]=useReveal();useEffect(()=>{if(!v)return;let s=0;const st=end/(duration/16);const iv=setInterval(()=>{s+=st;if(s>=end){sC(end);clearInterval(iv)}else sC(Math.floor(s))},16);return()=>clearInterval(iv)},[v,end,duration]);return <span ref={r}>{c}{suffix}</span>}

