/* ═══ CSS RAIN + STEAM OVERLAY ═══ */
function AtmosphericEffects() {
  return (
    <div style={{position:"absolute",inset:0,pointerEvents:"none",zIndex:1,overflow:"hidden"}}>
      {/* Rain streaks on glass */}
      {Array.from({length:35},(_,i)=>({
        left:5+Math.random()*90,delay:Math.random()*4,dur:0.8+Math.random()*0.6,
        opacity:0.08+Math.random()*0.12,height:40+Math.random()*80,
      })).map((d,i)=>(
        <div key={`r${i}`} style={{
          position:"absolute",left:`${d.left}%`,top:-100,
          width:1.2,height:d.height,
          background:`linear-gradient(180deg,transparent,rgba(180,200,220,${d.opacity}),transparent)`,
          animation:`rainFall ${d.dur}s ${d.delay}s linear infinite`,
          borderRadius:1,
        }}/>
      ))}
      {/* Glass droplets - static water beads */}
      {[
        {x:12,y:18,s:5},{x:28,y:32,s:3.5},{x:42,y:12,s:4},{x:58,y:42,s:3},
        {x:72,y:22,s:4.5},{x:85,y:38,s:3},{x:35,y:48,s:2.5},{x:62,y:15,s:3.5},
        {x:18,y:45,s:3},{x:78,y:8,s:4},{x:48,y:28,s:2.8},{x:92,y:25,s:3.2},
      ].map((d,i)=>(
        <div key={`d${i}`} style={{
          position:"absolute",left:`${d.x}%`,top:`${d.y}%`,
          width:d.s,height:d.s*1.3,borderRadius:"50%",
          background:"radial-gradient(circle at 35% 30%,rgba(210,225,240,.22),rgba(160,185,210,.06))",
          boxShadow:"0 1px 2px rgba(0,0,0,.08)",
        }}/>
      ))}
      {/* Steam wisps from coffee area */}
      {[0,1,2,3].map(i=>(
        <div key={`s${i}`} style={{
          position:"absolute",bottom:`${42+i*3}%`,left:`${28+i*2.5}%`,
          width:2,height:30+i*8,
          background:`linear-gradient(0deg,rgba(255,255,255,${0.04+i*0.01}),transparent)`,
          borderRadius:10,filter:"blur(2px)",
          animation:`steamRise ${3+i*0.6}s ${i*0.8}s ease-in-out infinite`,
          transformOrigin:"bottom center",
        }}/>
      ))}
      {/* Candle flicker glow */}
      <div style={{
        position:"absolute",bottom:"36%",left:"52%",
        width:60,height:60,borderRadius:"50%",
        background:"radial-gradient(circle,rgba(255,180,60,.06),transparent 70%)",
        animation:"candleFlicker 3s ease-in-out infinite",
      }}/>
      {/* Warm window light spill */}
      <div style={{
        position:"absolute",top:"10%",left:"20%",width:"60%",height:"50%",
        background:"radial-gradient(ellipse at 50% 40%,rgba(255,200,120,.025),transparent 65%)",
        animation:"ambientPulse 6s ease-in-out infinite",
      }}/>
    </div>
  );
}

function AmbientBar() {
  const [p,sP]=useState(false);
  return (
    <div onClick={()=>sP(!p)} style={{display:"inline-flex",alignItems:"center",gap:10,padding:"8px 18px",background:"rgba(255,255,255,.06)",border:"1px solid rgba(255,255,255,.1)",borderRadius:24,cursor:"pointer",transition:"all .2s",userSelect:"none"}}>
      <div style={{display:"flex",alignItems:"flex-end",gap:2,height:14}}>
        {[3,5,4,6,3,5,4].map((h,i)=>(
          <div key={i} style={{width:2.5,borderRadius:1,background:p?C.gold:"rgba(255,255,255,.3)",height:p?undefined:3,transition:"all .3s",animation:p?`eqBar .8s ${i*.1}s ease-in-out infinite alternate`:"none"}}/>
        ))}
      </div>
      <span style={{fontSize:12,fontWeight:600,color:"rgba(255,255,255,.5)"}}>{p?"☕ Lo-Fi Study Jazz":"♪ Study Ambience"}</span>
    </div>
  );
}

